#define OL_MAP_N ((int)(sizeof kOlMap / sizeof kOlMap[0]))
static int OlSame(const char *a, const char *b)  // case-blind, as the ini reads (GetPrivateProfileString + _stricmp)
{
    for (; *a && *b; ++a, ++b) {
        const int x = *a >= 'a' && *a <= 'z' ? *a - 32 : *a, y = *b >= 'a' && *b <= 'z' ? *b - 32 : *b;
        if (x != y) return 0;
    }
    return *a == *b;
}
static const char *OlShow(int map, const char *ini)  // the word the row shows for an ini word
{
    int i;
    if (!ini) return ini;
    for (i = 0; i < OL_MAP_N; ++i)
        if (kOlMap[i].map == map && OlSame(kOlMap[i].ini, ini)) return kOlMap[i].show;
    return ini;
}
static const char *OlIni(int map, const char *show)  // the ini word a shown word stands for
{
    int i;
    if (!show) return show;
    for (i = 0; i < OL_MAP_N; ++i)
        if (kOlMap[i].map == map && OlSame(kOlMap[i].show, show)) return kOlMap[i].ini;
    return show;
}

